'use strict';

var Linter = require( 'eslint' ).Linter;
var rule = require( './../lib' );

var linter = new Linter();
var code = [
	'var format = require( \'@stdlib/string/format\' );',
	'',
	'var str = format( \'%s %s\', \'foo\' );'
].join( '\n' );

linter.defineRule( 'format-args', rule );

var results = linter.verify( code, {
	'rules': {
		'format-args': 'error'
	}
});
console.log( results );
